package redact

import (
	"fmt"
	"testing"
)

// TestBetterleaksCoverageOfDBShapes is a diagnostic-only test that invokes the
// betterleaks default detector directly (bypassing the DB-specific layer added
// in this PR) and reports which DB credential shapes it catches on its own.
// The goal is to measure how much of the new DB layer is redundant with
// betterleaks's defaults vs. genuine new coverage.
//
// This test always passes; it prints a coverage table to test logs.
func TestBetterleaksCoverageOfDBShapes(t *testing.T) {
	t.Parallel()
	d := getDetector()
	if d == nil {
		t.Fatal("betterleaks detector unavailable")
	}

	cases := []struct {
		name  string
		input string
	}{
		// Postgres keyword DSN (low entropy)
		{"pg-keyword-low", `REDACTED,
		{"pg-keyword-high", `REDACTED,

		// SQL Server / ADO.NET semicolon
		{"mssql-low", `REDACTED,
		{"mssql-high", `REDACTED,

		// ODBC
		{"odbc-low", `REDACTED;`},
		{"odbc-high", `REDACTED;`},

		// JDBC URL with query password
		{"jdbc-low", `REDACTED`},
		{"jdbc-high", `REDACTED`},

		// DB URL with query password
		{"dburl-low", `https://db.example.com/connect?user=alice&password=hunter2`},
		{"dburl-high", `https://db.example.com/connect?user=alice&password=REDACTED`},

		// Bounded env-var assignments
		{"db-pwd-low", `DB_PASSWORD=REDACTED,
		{"db-pwd-high", `REDACTED,
		{"pgpassword-low", `PGPASSWORD=REDACTED,
		{"pgpassword-high", `REDACTED,
		{"redis-pwd-low", `REDIS_PASSWORD=REDACTED,
		{"redis-pwd-high", `REDACTED,
		{"mysql-root-low", `MYSQL_ROOT_PASSWORD=REDACTED,
		{"mysql-root-high", `REDACTED,

		// JSON fields
		{"json-low", `{"db":{"host":"localhost","user":"svc","password":"hunter2"}}`},
		{"json-high", `{"db":{"host":"localhost","user":"svc","password":"REDACTED"}}`},

		// Quoted ADO.NET with embedded semicolons (gap noted earlier)
		{"mssql-quoted-semi", `REDACTED,

		// Negative controls
		{"prose", `the user reset their password yesterday`},
		{"path", `/var/lib/postgresql/data/password.conf`},
	}

	t.Logf("%-22s | %-8s | %s", "case", "betterl", "input")
	t.Logf("%s", "---")
	for _, c := range cases {
		findings := d.DetectString(c.input)
		caught := "no"
		if len(findings) > 0 {
			caught = fmt.Sprintf("YES(%s)", findings[0].RuleID)
		}
		t.Logf("%-22s | %-8s | %s", c.name, caught, c.input)
	}
}

