package redact

import (
	"fmt"
	"sort"
	"testing"
)

// TestBetterleaksDBSpecificRules is diagnostic-only. It calls DetectString
// directly (no file path) against shapes that have first-party betterleaks
// rules, plus all the shapes the new DB layer in this PR adds. The intent is
// to answer: "which DB shapes does betterleaks alone catch out-of-the-box,
// and which require either path context or the new layer in this PR?"
func TestBetterleaksDBSpecificRules(t *testing.T) {
	t.Parallel()
	d := getDetector()
	if d == nil {
		t.Fatal("betterleaks detector unavailable")
	}

	cases := []struct {
		name  string
		input string
	}{
		// MongoDB rule has no Path: — should fire on raw input (entropy >= 4).
		{"mongodb-uri-high", `MONGODB_URI="REDACTED"`},
		{"mongodb-uri-srv-high", `REDACTED`},
		{"mongodb-uri-low", `MONGODB_URI="REDACTED"`},
		{"mongodb-uri-bare", `uri=REDACTED`},

		// Postgres URL form (no first-party rule — relies on credentialed-URI fallback)
		{"pg-url-high", `DATABASE_URL=REDACTED`},
		{"pg-url-low", `DATABASE_URL=REDACTED`},

		// Postgres keyword DSN (no URL — only the new layer in this PR can catch)
		{"pg-keyword-low", `REDACTED,
		{"pg-keyword-high", `REDACTED,

		// JDBC
		{"jdbc-low", `REDACTED`},
		{"jdbc-high", `REDACTED`},

		// SQL Server / ADO.NET semicolon
		{"mssql-low", `REDACTED,
		{"mssql-high", `REDACTED,

		// ODBC
		{"odbc-low", `REDACTED;`},

		// Redis
		{"redis-uri-high", `REDACTED`},
		{"redis-uri-low", `REDACTED`},

		// Bounded env var assignments
		{"db-pwd-low", `DB_PASSWORD=REDACTED,
		{"pgpassword-low", `PGPASSWORD=REDACTED,
		{"mysql-root-low", `MYSQL_ROOT_PASSWORD=REDACTED,

		// JSON
		{"json-db-low", `{"db":{"host":"localhost","user":"svc","password":"hunter2"}}`},
	}

	hits := map[string][]string{}
	t.Logf("%-22s | %s", "case", "betterleaks rule(s) fired")
	t.Logf("%s", "---")
	for _, c := range cases {
		findings := d.DetectString(c.input)
		caught := "—"
		if len(findings) > 0 {
			ids := make([]string, 0, len(findings))
			for _, f := range findings {
				ids = append(ids, f.RuleID)
				hits[f.RuleID] = append(hits[f.RuleID], c.name)
			}
			caught = fmt.Sprintf("%v", ids)
		}
		t.Logf("%-22s | %s", c.name, caught)
	}

	t.Logf("---")
	t.Logf("Rules fired across cases:")
	keys := make([]string, 0, len(hits))
	for k := range hits {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		t.Logf("  %-32s -> %v", k, hits[k])
	}
}

