166					continue
167				}
168				searchFrom := 0
169				for {
170					idx := strings.Index(s[searchFrom:], f.Secret)
171					if idx < 0 {
172						break
173					}
174					absIdx := searchFrom + idx
175					regions = append(regions, taggedRegion{region: region{absIdx, absIdx + len(f.Secret)}})
176					searchFrom = absIdx + len(f.Secret)
177				}
178			}
179		}
180	
181		// 3. Credentialed URIs (secrets — always on).
182		for _, loc := range credentialedURIPattern.FindAllStringIndex(s, -1) {
183			regions = append(regions, taggedRegion{region: region{loc[0], loc[1]}})
184		}
185	
186		// 4. Database and connection-string detection (secrets — always on).
187		regions = append(regions, detectConnectionStrings(s)...)
188	
189		// 5. Bounded credential key/value detection (secrets — always on).
190		regions = append(regions, detectCredentialValues(s)...)
191	
192		// 6. PII detection (opt-in — only runs when configured).
193		regions = append(regions, detectPII(getPIIConfig(), s)...)
194	
195		if len(regions) == 0 {
196			return s
197		}
198	
199		// Merge overlapping regions and build result.
200		sort.Slice(regions, func(i, j int) bool {
201			if regions[i].start != regions[j].start {
202				return regions[i].start < regions[j].start
203			}
204			if regions[i].end != regions[j].end {
205				return regions[i].end > regions[j].end // larger region first
206			}
207			return regions[i].label < regions[j].label // deterministic tie-break
208		})
209		merged := []taggedRegion{regions[0]}
210		for _, r := range regions[1:] {
211			last := &merged[len(merged)-1]
212			if r.start <= last.end {
213				if r.end > last.end {
214					last.end = r.end
215				}
216				// Keep the existing label (first/larger region wins)
217			} else {
218				merged = append(merged, r)
219			}
220		}
221	
222		var b strings.Builder
223		prev := 0
224		for _, r := range merged {
225			b.WriteString(s[prev:r.start])
226			b.WriteString(replacementToken(r.label))
227			prev = r.end
228		}
229		b.WriteString(s[prev:])
230		return b.String()
231	}
232	
233	func detectConnectionStrings(s string) []taggedRegion {
234		var regions []taggedRegion
235		for _, rule := range connectionStringRules {
236			regions = append(regions, detectConnectionStringRule(s, rule)...)
237		}
238		return regions
239	}
240	
241	func detectConnectionStringRule(s string, rule connectionStringRule) []taggedRegion {
242		var regions []taggedRegion
243		for _, loc := range rule.pattern.FindAllStringIndex(s, -1) {
244			start, end := loc[0], trimConnectionStringEnd(s, loc[0], loc[1])
245			if start >= end {
246				continue
247			}
248			if rule.hasSecret(s[start:end]) {
249				regions = append(regions, taggedRegion{region: region{start, end}})
250			}
251		}
252		return regions
253	}
254	
255	func trimConnectionStringEnd(s string, start, end int) int {
256		for end > start {
257			switch s[end-1] {
258			case '.', ',', ';', ':', '!', '?', ')', ']':
259				end--
260			default:
261				return end
262			}
263		}
264		return end
265	}
266	
267	func hasJDBCPassword(candidate string) bool {
268		if !strings.HasPrefix(strings.ToLower(candidate), "jdbc:") {
269			return false
270		}
271		return hasNonPlaceholderPasswordAssignment(candidate)
272	}
273	
274	func hasDatabaseURLSecret(candidate string) bool {
275		u, err := url.Parse(candidate)
276		if err != nil || u.Scheme == "" || u.Host == "" {
277			return false
278		}
279		for key, values := range u.Query() {
280			if !isPasswordQueryKey(key) {
281				continue
282			}
283			for _, value := range values {
284				if hasNonPlaceholderPasswordValue(value) {
285					return true
286				}
287			}
288		}
289		return false
290	}
291	
292	func isPasswordQueryKey(key string) bool {
293		return strings.EqualFold(key, "password") || strings.EqualFold(key, "pwd")
294	}
295	
296	func hasKeywordDSNPassword(candidate string) bool {
297		return keywordHostPattern.MatchString(candidate) &&
298			keywordUserPattern.MatchString(candidate) &&
299			hasNonPlaceholderPasswordAssignment(candidate)
300	}
301	
302	func hasSemicolonConnectionPassword(candidate string) bool {
303		return semicolonServerPattern.MatchString(candidate) &&
304			semicolonUserPattern.MatchString(candidate) &&
305			hasNonPlaceholderPasswordAssignment(candidate)
306	}
307	
308	func detectCredentialValues(s string) []taggedRegion {
309		var regions []taggedRegion
310		for _, loc := range credentialValuePattern.FindAllStringSubmatchIndex(s, -1) {
311			if len(loc) < 6 || loc[4] < 0 || loc[5] < 0 {
312				continue
313			}
314			start, end := unquoteRange(s, loc[4], loc[5])
315			if hasNonPlaceholderPasswordValue(s[start:end]) {
316				regions = append(regions, taggedRegion{region: region{start, end}})
317			}
318		}
319		return regions
320	}
321	
322	func unquoteRange(s string, start, end int) (int, int) {
323		if end-start < 2 {
324			return start, end
325		}
326		first, last := s[start], s[end-1]
327		if (first == '"' && last == '"') || (first == '\'' && last == '\'') {
328			return start + 1, end - 1
329		}
330		return start, end
331	}
332	
333	func hasNonPlaceholderPasswordAssignment(candidate string) bool {
334		for _, loc := range passwordAssignmentRegex.FindAllStringSubmatchIndex(candidate, -1) {
335			if len(loc) >= 4 && loc[2] >= 0 && loc[3] >= 0 {
336				start, end := unquoteRange(candidate, loc[2], loc[3])
337				if hasNonPlaceholderPasswordValue(candidate[start:end]) {
338					return true
339				}
340			}
341		}
342		return false
343	}
344	
345	func hasNonPlaceholderPasswordValue(value string) bool {
346		return value != "" && !isPlaceholderSecretValue(value)
347	}
348	
349	func isPlaceholderSecretValue(value string) bool {
350		normalized := strings.ToLower(strings.TrimSpace(value))
351		normalized = strings.Trim(normalized, `"'`)
352		if normalized == "" {
353			return true
354		}
355		if strings.HasPrefix(normalized, "${") && strings.HasSuffix(normalized, "}") {
356			return true
357		}
358		switch normalized {
359		case "redacted", "[redacted]", "<redacted>", "xxx", "xxxx", "changeme", "example":
360			return true
361		default:
362			return false
363		}
364	}
365	
366	func isCredentialJSONSecretKey(key string, credentialContext bool) bool {
367		normalized := normalizeCredentialJSONKey(key)
368		if credentialJSONKeyRegex.MatchString(normalized) {
369			return true
370		}
371		return credentialContext && genericPasswordKeyRegex.MatchString(normalized)
372	}
373	
374	func isCredentialJSONObject(obj map[string]any) bool {
375		hasHost := hasJSONKey(obj, "host", "hostname", "server", "addr", "address", "datasource", "data_source")
376		hasUser := hasJSONKey(obj, "user", "username", "userid", "user_id", "uid")
377		return hasHost && hasUser
378	}
379	
380	func hasJSONKey(obj map[string]any, keys ...string) bool {
381		for key := range obj {
382			normalized := normalizeCredentialJSONKey(key)
383			for _, want := range keys {
384				if normalized == want {
385					return true
386				}
387			}
388		}
389		return false
390	}
391	
392	func normalizeCredentialJSONKey(key string) string {
393		key = strings.ToLower(strings.TrimSpace(key))
394		key = strings.ReplaceAll(key, "-", "_")
395		key = strings.ReplaceAll(key, " ", "_")
396		return key
397	}
398	
399	// Bytes is a convenience wrapper around String for []byte content.
400	func Bytes(b []byte) []byte {
401		s := string(b)
402		redacted := String(s)
403		if redacted == s {
404			return b
405		}
406		return []byte(redacted)
407	}
408	
409	// JSONLBytes redacts secrets in JSONL-formatted byte content and returns
410	// the result as RedactedBytes, certifying the output has been through redaction.
411	func JSONLBytes(b []byte) (RedactedBytes, error) {
412		s := string(b)
413		redacted, err := JSONLContent(s)
414		if err != nil {
415			return RedactedBytes{}, err
416		}
417		if redacted == s {
418			return RedactedBytes{data: b}, nil
419		}
420		return RedactedBytes{data: []byte(redacted)}, nil
421	}
422	
423	// JSONLContent parses each line as JSON to determine which string values
424	// need redaction, then performs targeted replacements on the raw JSON bytes.
425	// Lines with no secrets are returned unchanged, preserving original formatting.
426	//
427	// For multi-line JSON content (e.g., pretty-printed single JSON objects like
428	// OpenCode export), the function first attempts to parse the entire content as
429	// a single JSON value. This ensures field-aware redaction (which skips ID fields)
430	// is used instead of falling back to entropy-based detection on raw text lines,
431	// which would corrupt high-entropy identifiers.
432	func JSONLContent(content string) (string, error) {
433		// Try parsing the entire content as a single JSON value first.
434		// Uses a streaming decoder to avoid copying the full content into []byte.
435		// After decoding, attempts a second Decode to confirm EOF — if it succeeds,
436		// the content is JSONL (multiple values) and we fall through to line-by-line.
437		trimmed := strings.TrimSpace(content)
438		if len(trimmed) > 0 {
439			dec := json.NewDecoder(strings.NewReader(trimmed))
440			var parsed any
441			if err := dec.Decode(&parsed); err == nil && isSingleJSONValue(dec) {
442				// Content is a single JSON value (object/array) — redact field-aware.
443				result, err := applyJSONReplacements(content, collectJSONLReplacements(parsed))
444				if err != nil {
445					return "", err
446				}
447				return result, nil
448			}
449		}
450	
451		// Fall back to line-by-line JSONL processing.
452		lines := strings.Split(content, "\n")
453		var b strings.Builder
454		for i, line := range lines {
455			if i > 0 {
456				b.WriteByte('\n')
457			}
458			lineTrimmed := strings.TrimSpace(line)
459			if lineTrimmed == "" {
460				b.WriteString(line)
461				continue
462			}
463			var parsed any
464			if err := json.Unmarshal([]byte(lineTrimmed), &parsed); err != nil {
465				b.WriteString(String(line))
466				continue
467			}
468			result, err := applyJSONReplacements(line, collectJSONLReplacements(parsed))
469			if err != nil {
470				return "", err
471			}
472			b.WriteString(result)
473		}
474		return b.String(), nil
475	}
476	
477	// applyJSONReplacements applies collected (original, redacted) string pairs
478	// to the raw JSON text, replacing JSON-encoded originals with their redacted forms.
479	// Returns s unchanged if repls is empty.
480	func applyJSONReplacements(s string, repls []jsonReplacement) (string, error) {
481		if len(repls) == 0 {
482			return s, nil
483		}
484		for _, r := range repls {
485			origJSON, err := jsonEncodeString(r.original)
486			if err != nil {
487				return "", err
488			}
489			replJSON, err := jsonEncodeString(r.redacted)
490			if err != nil {
491				return "", err
492			}
493			if r.key == "" {
494				s = strings.ReplaceAll(s, origJSON, replJSON)
495				continue
496			}
497			keyJSON, err := jsonEncodeString(r.key)
498			if err != nil {
499				return "", err
500			}
501			pattern := regexp.MustCompile(`(` + regexp.QuoteMeta(keyJSON) + `\s*:\s*)` + regexp.QuoteMeta(origJSON))
502			s = pattern.ReplaceAllStringFunc(s, func(match string) string {
503				idx := strings.LastIndex(match, origJSON)
504				if idx < 0 {
505					return match
506				}
507				return match[:idx] + replJSON
508			})
509		}
510		return s, nil
511	}
512	
513	// isSingleJSONValue returns true if the decoder has reached EOF (no more
514	// top-level values). This distinguishes a single JSON value (e.g., pretty-printed
515	// object) from JSONL (multiple concatenated values). We attempt a second Decode
516	// and require io.EOF rather than relying on dec.More(), which is documented for
517	// use inside arrays/objects and not for top-level value boundaries.
518	func isSingleJSONValue(dec *json.Decoder) bool {
519		var discard json.RawMessage
520		return dec.Decode(&discard) == io.EOF
521	}
522	
523	// collectJSONLReplacements walks a parsed JSON value and collects unique string
524	// replacements for values that need redaction.
525	func collectJSONLReplacements(v any) []jsonReplacement {
526		seen := make(map[string]bool)
527		var repls []jsonReplacement
528		var walk func(key string, credentialContext bool, v any)
529		walk = func(key string, credentialContext bool, v any) {
530			switch val := v.(type) {
531			case map[string]any:
532				if shouldSkipJSONLObject(val) {
533					return
534				}
535				childCredentialContext := credentialContext || isCredentialJSONObject(val)
536				for k, child := range val {
537					if shouldSkipJSONLField(k) {
538						continue
539					}
540					walk(k, childCredentialContext, child)
541				}
542			case []any:
543				for _, child := range val {
544					walk("", credentialContext, child)
545				}
546			case string:
547				redacted := String(val)
548				replacementKey := ""
549				if key != "" {
550					replacementKey = key
551				}
552				if redacted == val && isCredentialJSONSecretKey(key, credentialContext) && hasNonPlaceholderPasswordValue(val) {
553					redacted = RedactedPlaceholder
554				}
555				if redacted != val {
556					seenKey := replacementKey + "\x00" + val
557					if !seen[seenKey] {
558						seen[seenKey] = true
559						repls = append(repls, jsonReplacement{key: replacementKey, original: val, redacted: redacted})
560					}
561				}
562			}
563		}
564		walk("", false, v)
565		return repls
566	}
567	
568	// shouldSkipJSONLField returns true if a JSON key should be excluded from scanning/redaction.
569	// Skips "signature" (exact), ID fields (ending in "id"/"ids"), and common path/directory fields.
570	func shouldSkipJSONLField(key string) bool {
571		if key == "signature" {
572			return true
573		}
574		lower := strings.ToLower(key)
575	
576		// Skip ID fields
577		if strings.HasSuffix(lower, "id") || strings.HasSuffix(lower, "ids") {
578			return true
579		}
580	
581		// Skip common path and directory fields from agent transcripts.
582		// These appear frequently in tool calls and are structural, not secrets.
583		switch lower {
584		case "filepath", "file_path", "cwd", "root", "directory", "dir", "path":
585			return true
586		}
587	
588		return false
589	}
590	
591	// shouldSkipJSONLObject returns true if the object has "type":"image" or "type":"image_url".
592	func shouldSkipJSONLObject(obj map[string]any) bool {
593		t, ok := obj["type"].(string)
594		return ok && (strings.HasPrefix(t, "image") || t == "base64")
595	}
596	
597	func shannonEntropy(s string) float64 {
598		if len(s) == 0 {
599			return 0
600		}
601		freq := make(map[byte]int)
602		for i := range len(s) {
603			freq[s[i]]++
604		}
605		length := float64(len(s))
606		var entropy float64
607		for _, count := range freq {
608			p := float64(count) / length
609			entropy -= p * math.Log2(p)
610		}
611		return entropy
612	}
613	
614	// jsonEncodeString returns the JSON encoding of s without HTML escaping.
615	func jsonEncodeString(s string) (string, error) {
616		var buf bytes.Buffer
617		enc := json.NewEncoder(&buf)
618		enc.SetEscapeHTML(false)
619		if err := enc.Encode(s); err != nil {
620			return "", fmt.Errorf("json encode string: %w", err)
621		}
622		return strings.TrimSuffix(buf.String(), "\n"), nil
623	}
624

